struct po {
    float data[16];
} __attribute__((aligned(16)));

struct frame_info {
    float age;
    int ifl_frame_boost;
    int ifl_frame_locked;
};

struct vector3d {
    float x;
    float y;
    float z;
};

struct instance_render_info {
    float number_of_faces_to_attempt;
    po local_to_world;
    unsigned int force_flags;
    unsigned int color_scale;
    float camera_relative_rotation;
    frame_info frame_time_info;
    void *my_region;
    float particle_scale;
    void *my_light_set;
    void *alt_materials;
    int frame;
    vector3d render_scale;
};

extern "C" void adjust_heap(
    instance_render_info *,
    int,
    int,
    instance_render_info
) __asm__("__adjust_heap__H3ZP20instance_render_infoZiZ20instance_render_info_X01X11X11X21_v");

__asm__(".equ __adjust_heap__H3ZP20instance_render_infoZiZ20instance_render_info_X01X11X11X21_v,0x002F17C0");

extern "C" void make_heap(
    instance_render_info *,
    instance_render_info *,
    instance_render_info *,
    int *
) __asm__("__make_heap__H3ZP20instance_render_infoZ20instance_render_infoZi_X01X01PX11PX21_v");

void make_heap(
    instance_render_info *first,
    instance_render_info *last,
    instance_render_info *,
    int *
) {
    if (last - first < 2)
        return;
    int len = last - first;
    int parent = (len - 2) / 2;

    while (true) {
        instance_render_info value = *(first + parent);
        adjust_heap(first, parent, len, value);
        if (parent == 0)
            return;
        parent--;
    }
}
